ai-exam-day-2:
function applyBpeMerges(tokens, mergeRules) {
  let current = [...tokens];
  for (const [pairA, pairB, merged] of mergeRules) {
    const next = [];
    let i = 0;
    while (i < current.length) {
      if (i < current.length - 1 && current[i] === pairA && current[i + 1] === pairB) {
        next.push(merged);
        i += 2;
      } else {
        next.push(current[i]);
        i++;
      }
    }
    current = next;
  }
  return current;
}

