  const compressionRatio = (loraParams / fullParams) * 100;
  return {
    d_model,
    rank_r: r,
    fullParameters: fullParams,
    trainableLoraParameters: loraParams,
    trainablePercent: `${compressionRatio.toFixed(2)}%`
  };
}

