  const dataKey = Array.from({ length: 16 }, (_, i) => (i * 37 + plainData.length) % 256);
  const ciphertext = Array.from(plainData, (ch, i) => (ch.charCodeAt(0) ^ dataKey[i % dataKey.length]).toString(16).padStart(2, '0')).join('');
  const encryptedDataKey = dataKey.map((b) => (b ^ 0xaa).toString(16).padStart(2, '0')).join('');
  return { ciphertext, encryptedDataKey, kmsMasterKeyId: masterKeyArn };
}

