  const isDangerous = hasJavaMagic || hasPythonPickle || hasPhpObject;
  return {
    isDangerousObjectSerialization: isDangerous,
    formatDetected: hasJavaMagic ? 'Java Serialization' : hasPythonPickle ? 'Python Pickle' : hasPhpObject ? 'PHP Object' : 'Safe/Unknown',
