  if (pref === 'top' && topY - tipHeight < 0) {
    actualPlacement = 'bottom';
  } else if (pref === 'bottom' && topY + tipHeight > viewHeight) {
    actualPlacement = 'top';
  }
  return {
    preferredPlacement: pref,
    resolvedPlacement: actualPlacement,
    isFlipped: actualPlacement !== pref,
    status: 'FLOATING_PLACEMENT_RESOLVED_NOMINAL'
  };
}

