  } else if (key === 'ArrowLeft' || key === 'ArrowUp') {
    next = (curr - 1 + total) % total;
  }
  return {
    previousIndex: curr,
    newActiveIndex: next,
    isIndexChanged: next !== curr,
    status: 'ROVING_TABINDEX_RESOLVED_NOMINAL'
  };
}

