devops-exam-day-11:
function determineNextSemVer(current, commits) {
  let [major, minor, patch] = current.split('.').map(Number);
  const breaking = commits.some((c) => /BREAKING CHANGE/.test(c) || /^\w+(\(.+\))?!:/.test(c));
  const feat = commits.some((c) => /^feat(\(.+\))?:/.test(c));
  const fix = commits.some((c) => /^fix(\(.+\))?:/.test(c));
  if (breaking) return (major + 1) + '.0.0';
  if (feat) return major + '.' + (minor + 1) + '.0';
  if (fix) return major + '.' + minor + '.' + (patch + 1);
  return current;
}

