  const results = await Promise.all(endpoints.map(async (url) => ({ url, res: await client.get(url) })));
  const failedEndpoints = results.filter(({ res }) => res.status !== 200 || res.latencyMs > 2000).map(({ url }) => url);
  const healthy = failedEndpoints.length === 0;
  return { deploymentHealthy: healthy, shouldRollback: !healthy, failedEndpoints };
}

devops-exam-day-15:
async function executeEnterprisePipeline(stages, executeRollback) {
  const completedStages = [];
  for (const stage of stages) {
    const result = await stage.action();
    if (!result || !result.success) {
      if (executeRollback) await executeRollback();
      return { pipelineSuccess: false, failedStage: stage.name, completedStages };
    }
    completedStages.push(stage.name);
  }
  return { pipelineSuccess: true, failedStage: null, completedStages };
}

