function reconcileReplicaSet(desired, currentPods) {
  const running = currentPods.filter((p) => p.status === 'Running').length;
  if (desired > running) return { action: 'SCALE_UP', count: desired - running };
  if (desired < running) return { action: 'SCALE_DOWN', count: running - desired };
  return { action: 'IN_SYNC', count: 0 };
}

