devops-exam-day-2:
function handleProcessSignal(signal, connections, timeoutMs) {
  if (signal === 'SIGTERM') return { action: 'DRAIN_CONNECTIONS', shouldExit: true, exitCode: 0, connectionsToDrain: connections, timeoutMs };
  if (signal === 'SIGKILL') return { action: 'FORCE_IMMEDIATE_TERMINATION', shouldExit: true, exitCode: 137 };
  if (signal === 'SIGHUP') return { action: 'RELOAD_CONFIGURATION', shouldExit: false, exitCode: null };
  return { action: 'IGNORE', shouldExit: false, exitCode: null };
}

