  const breached = failures >= threshold;
  if (!breached) return { action: 'CONTINUE_SERVING', breached: false };
  if (type === 'liveness') return { action: 'RESTART_CONTAINER', breached: true };
  if (type === 'readiness') return { action: 'REMOVE_FROM_ENDPOINTS', breached: true };
  return { action: 'RESTART_CONTAINER', breached: true };
}

