function totalNQueens(n) {
  const cols = new Set(), pos = new Set(), neg = new Set();
  let count = 0;
  (function place(r) {
    if (r === n) { count++; return; }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || pos.has(r + c) || neg.has(r - c)) continue;
      cols.add(c); pos.add(r + c); neg.add(r - c);
      place(r + 1);
      cols.delete(c); pos.delete(r + c); neg.delete(r - c);
    }
  })(0);
  return count;
}

