function findCheapestFlight(n, flights, src, dst, k) {
  let cost = new Array(n).fill(Infinity);
  cost[src] = 0;
  for (let i = 0; i <= k; i++) {
    const next = cost.slice();
    for (const [u, v, w] of flights) if (cost[u] + w < next[v]) next[v] = cost[u] + w;
    cost = next;
  }
  return cost[dst] === Infinity ? -1 : cost[dst];
}

