class CircularQueue {
  constructor(k) { this.data = new Array(k); this.k = k; this.head = 0; this.count = 0; }
  enQueue(value) {
    if (this.isFull()) return false;
    this.data[(this.head + this.count) % this.k] = value; this.count++;
    return true;
  }
  deQueue() {
    if (this.isEmpty()) return false;
    this.head = (this.head + 1) % this.k; this.count--;
    return true;
  }
  Front() { return this.isEmpty() ? -1 : this.data[this.head]; }
  Rear() { return this.isEmpty() ? -1 : this.data[(this.head + this.count - 1) % this.k]; }
  isEmpty() { return this.count === 0; }
  isFull() { return this.count === this.k; }
}

