class MyHashMap {
  constructor() { this.size = 101; this.buckets = Array.from({ length: this.size }, () => []); }
  _hash(key) { return key % this.size; }
  put(key, value) {
    const bucket = this.buckets[this._hash(key)];
    const pair = bucket.find((p) => p[0] === key);
    if (pair) pair[1] = value; else bucket.push([key, value]);
  }
  get(key) {
    const pair = this.buckets[this._hash(key)].find((p) => p[0] === key);
    return pair ? pair[1] : -1;
  }
  remove(key) {
    const i = this._hash(key);
    this.buckets[i] = this.buckets[i].filter((p) => p[0] !== key);
  }
}

