class NetworkFirewallEngine {
    activeConnections = new Set();
    evaluateSecurityGroup(packet, rules) {
        if (packet.isReturnTraffic) return true;
        return rules.some((r) => r.type === 'inbound' && r.port === packet.destPort);
    }
    evaluateNACL(packet, rules, isOutbound) {
        const direction = isOutbound ? 'outbound' : 'inbound';
        const ordered = rules.filter((r) => r.type === direction).sort((a, b) => a.ruleNumber - b.ruleNumber);
        for (const rule of ordered) {
            const [from, to] = rule.portRange;
            if (packet.destPort >= from && packet.destPort <= to) return rule.action === 'ALLOW';
        }
        return false;
    }
}

