class ECSDeploymentController {
    calculateRollingCapacity(config) {
        return {
            minTasks: Math.ceil((config.desiredCount * config.minimumHealthyPercent) / 100),
            maxTasks: Math.floor((config.desiredCount * config.maximumPercent) / 100)
        };
    }
    validateTaskDefinition(taskDef) {
        const cpu = Number(taskDef.cpu);
        const memory = Number(taskDef.memory);
        const ranges = { 256: [512, 2048], 512: [1024, 4096], 1024: [2048, 8192], 2048: [4096, 16384], 4096: [8192, 30720] };
        const range = ranges[cpu];
        if (!range || memory < range[0] || memory > range[1]) return false;
