class CompositeAlarmEngine {
  constructor() {
    this.metricAlarms = new Map();
    this.compositeAlarms = new Map();
  }

  registerMetricAlarm(name, m, n, threshold) {
    this.metricAlarms.set(name, {
      m, n, threshold,
      history: [],
      state: 'OK'
    });
  }

  recordDatapoint(name, value) {
    const alarm = this.metricAlarms.get(name);
    if (!alarm) throw new Error(`Metric alarm ${name} not registered`);

    const isBreach = value >= alarm.threshold;
    alarm.history.push(isBreach);
    if (alarm.history.length > alarm.n) {
      alarm.history.shift();
    }

    const breachCount = alarm.history.filter(Boolean).length;
    alarm.state = (alarm.history.length >= alarm.n && breachCount >= alarm.m) ? 'ALARM' : 'OK';
    return alarm.state;
  }

  registerCompositeAlarm(name, ruleFn, suppressorAlarmName = null) {
    this.compositeAlarms.set(name, { ruleFn, suppressorAlarmName });
  }

  evaluateComposite(name) {
    const composite = this.compositeAlarms.get(name);
    if (!composite) throw new Error(`Composite alarm ${name} not registered`);

    const states = {};
    for (const [k, v] of this.metricAlarms.entries()) {
      states[k] = v.state;
    }

    const isTriggered = Boolean(composite.ruleFn(states));
    const compositeState = isTriggered ? 'ALARM' : 'OK';

    let actionsSuppressed = false;
    let suppressionReason = null;
    if (composite.suppressorAlarmName) {
      const suppressor = this.metricAlarms.get(composite.suppressorAlarmName);
      if (suppressor && suppressor.state === 'ALARM') {
        actionsSuppressed = true;
        suppressionReason = 'Actions suppressed by ' + composite.suppressorAlarmName;
      }
    }

    return {
      state: compositeState,
      actionsSuppressed,
      reason: suppressionReason || (isTriggered ? 'Rule condition satisfied' : 'Rule condition not met')
    };
  }
}

fullstack-js-assign-day-108:
class EdgeCacheSimulator {
  constructor(originFetchFn) {
    this.originFetchFn = originFetchFn;
    this.cache = new Map();
    this.inFlightRequests = new Map();
    this.originCallCount = 0;
  }

  async fetch(url, nowMs) {
    const cached = this.cache.get(url);

    if (cached) {
      const ageSec = (nowMs - cached.timestamp) / 1000;
      if (ageSec <= cached.sMaxAge) {
        return { body: cached.body, status: 'HIT', originCalls: this.originCallCount };
      }
      if (ageSec <= cached.sMaxAge + cached.staleWhileRevalidate) {
        this._revalidateInBackground(url, nowMs);
        return { body: cached.body, status: 'STALE_HIT', originCalls: this.originCallCount };
      }
    }

    if (!this.inFlightRequests.has(url)) {
      const fetchPromise = (async () => {
        this.originCallCount++;
        const originResp = await this.originFetchFn(url);
        this.cache.set(url, {
          body: originResp.body,
          timestamp: nowMs,
          sMaxAge: originResp.sMaxAge,
          staleWhileRevalidate: originResp.staleWhileRevalidate
        });
        this.inFlightRequests.delete(url);
        return originResp.body;
      })();
      this.inFlightRequests.set(url, fetchPromise);
    }

    const body = await this.inFlightRequests.get(url);
    return { body, status: 'MISS', originCalls: this.originCallCount };
  }

  _revalidateInBackground(url, nowMs) {
    if (this.inFlightRequests.has(url)) return;
    const p = (async () => {
      this.originCallCount++;
      const originResp = await this.originFetchFn(url);
      this.cache.set(url, {
        body: originResp.body,
        timestamp: nowMs,
        sMaxAge: originResp.sMaxAge,
        staleWhileRevalidate: originResp.staleWhileRevalidate
      });
      this.inFlightRequests.delete(url);
    })();
    this.inFlightRequests.set(url, p);
  }
}

fullstack-js-assign-day-109:
class ConsistentHashRing {
  constructor(vnodesPerNode = 128, sha256Hex) {
    this.vnodesPerNode = vnodesPerNode;
    this.sha256Hex = sha256Hex;
    this.ring = []; // sorted array of { hash: number, node: string }
  }

  _hash(str) {
    const hashHex = this.sha256Hex(str);
    return parseInt(hashHex.substring(0, 8), 16);
  }

  addNode(nodeName) {
    for (let i = 0; i < this.vnodesPerNode; i++) {
      const vnodeKey = `${nodeName}#vnode${i}`;
      const hash = this._hash(vnodeKey);
      this.ring.push({ hash, node: nodeName });
    }
    this.ring.sort((a, b) => a.hash - b.hash);
  }

  removeNode(nodeName) {
    this.ring = this.ring.filter(item => item.node !== nodeName);
  }

  getNode(key) {
    if (this.ring.length === 0) return null;
    const keyHash = this._hash(key);

    let low = 0;
    let high = this.ring.length - 1;
    let targetIndex = 0;

    if (keyHash > this.ring[high].hash) {
      return this.ring[0].node;
    }

    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      if (this.ring[mid].hash >= keyHash) {
        targetIndex = mid;
        high = mid - 1;
      } else {
        low = mid + 1;
      }
    }
    return this.ring[targetIndex].node;
  }
}

