class ParameterizedCostEstimator {
  constructor(pricingSchedule) {
    this.pricing = pricingSchedule;
  }

  estimateAnnualTCO(spec) {
    const { region, instanceType, instanceCount, storageGB, monthlyEgressGB, commitmentTier } = spec;

    const computeRate = this.pricing.computeHourly[region]?.[instanceType] || 0.10;
    const storageRate = this.pricing.storagePerGBMonthly[region] || 0.10;
    const egressRate = this.pricing.egressPerGB[region] || 0.08;

    const discountMultiplier = commitmentTier === '3YrSavings' ? 0.50 : (commitmentTier === '1YrSavings' ? 0.70 : 1.0);

    const monthlyComputeBase = instanceCount * computeRate * 730;
    const monthlyComputeDiscounted = monthlyComputeBase * discountMultiplier;
    const monthlyStorage = storageGB * storageRate;
    const monthlyEgress = monthlyEgressGB * egressRate;

    const monthlyTotal = monthlyComputeDiscounted + monthlyStorage + monthlyEgress;
    const annualTotal = monthlyTotal * 12;

    const onDemandAnnual = (monthlyComputeBase + monthlyStorage + monthlyEgress) * 12;
    const savingsVsOnDemand = Math.max(0, onDemandAnnual - annualTotal);

    return {
      monthlyCostUSD: Math.round(monthlyTotal),
      annualCostUSD: Math.round(annualTotal),
      savingsVsOnDemandUSD: Math.round(savingsVsOnDemand)
    };
  }
}

fullstack-js-assign-day-112:
class CircuitBreaker {
  constructor(options = {}) {
    this.failureThreshold = options.failureThreshold || 0.5;
    this.windowSize = options.windowSize || 10;
    this.resetTimeoutMs = options.resetTimeoutMs || 5000;
    this.state = 'CLOSED';
    this.history = [];
    this.lastStateChange = 0;
  }

  async execute(actionFn, fallbackFn, nowMs = Date.now()) {
    if (this.state === 'OPEN') {
      if (nowMs - this.lastStateChange >= this.resetTimeoutMs) {
        this.state = 'HALF-OPEN';
        this.lastStateChange = nowMs;
      } else {
        return { executed: false, result: fallbackFn(new Error('Circuit breaker is OPEN')) };
      }
    }

    try {
      const result = await actionFn();
      this._onSuccess();
      return { executed: true, result };
    } catch (err) {
      this._onFailure(nowMs);
      return { executed: false, result: fallbackFn(err) };
    }
  }

  _onSuccess() {
    if (this.state === 'HALF-OPEN') {
      this.state = 'CLOSED';
      this.history = [];
    } else if (this.state === 'CLOSED') {
      this.history.push(true);
      if (this.history.length > this.windowSize) this.history.shift();
    }
  }

  _onFailure(nowMs) {
    if (this.state === 'HALF-OPEN') {
      this.state = 'OPEN';
      this.lastStateChange = nowMs;
    } else if (this.state === 'CLOSED') {
      this.history.push(false);
      if (this.history.length > this.windowSize) this.history.shift();

      const failCount = this.history.filter(s => !s).length;
      if (this.history.length >= this.windowSize && (failCount / this.windowSize) >= this.failureThreshold) {
        this.state = 'OPEN';
        this.lastStateChange = nowMs;
      }
    }
  }
}

