class ReadWriteRouter {
  constructor(primaryPinningWindowMs = 5000) {
    this.pinningWindowMs = primaryPinningWindowMs;
    this.sessionWrites = new Map();
  }

  recordWrite(sessionId, nowMs) {
    this.sessionWrites.set(sessionId, nowMs);
  }

  route(sessionId, queryType, nowMs) {
    if (queryType === 'WRITE') {
      this.recordWrite(sessionId, nowMs);
      return 'PRIMARY';
    }

    const lastWrite = this.sessionWrites.get(sessionId);
    if (lastWrite !== undefined && (nowMs - lastWrite) < this.pinningWindowMs) {
      return 'PRIMARY';
    }

    return 'REPLICA';
  }
}

