class SemanticVectorIndex {
  constructor() {
    this.documents = [];
  }

  insert(id, vector, metadata = {}) {
    this.documents.push({ id, vector, metadata });
  }

  searchTopK(queryVector, k = 3) {
    const scored = this.documents.map(doc => {
      const dot = queryVector.reduce((sum, val, i) => sum + val * doc.vector[i], 0);
      const normQ = Math.sqrt(queryVector.reduce((sum, val) => sum + val * val, 0));
      const normD = Math.sqrt(doc.vector.reduce((sum, val) => sum + val * val, 0));
      const denom = normQ * normD;
      const distance = denom === 0 ? 1.0 : 1.0 - (dot / denom);
      return { id: doc.id, distance, metadata: doc.metadata };
    });
    scored.sort((a, b) => a.distance - b.distance);
    return scored.slice(0, k);
  }
}

