class VectorBenchmarkHarness {
  constructor(dataset) {
    this.dataset = dataset;
  }

  _dist(u, v) {
    return Math.sqrt(u.reduce((sum, val, i) => sum + Math.pow(val - v[i], 2), 0));
  }

  exactSearch(queryVector, filterTenantId = null, k = 5) {
    let pool = this.dataset;
    if (filterTenantId) {
      pool = pool.filter(d => d.tenantId === filterTenantId);
    }
    const scored = pool.map(d => ({ id: d.id, dist: this._dist(queryVector, d.vector) }));
    scored.sort((a, b) => a.dist - b.dist);
    return scored.slice(0, k).map(d => d.id);
  }

  approximateSearch(queryVector, filterTenantId = null, k = 5, useIterativeScan = false) {
    if (filterTenantId && !useIterativeScan) {
      const globalScored = this.dataset.map(d => ({ id: d.id, tenantId: d.tenantId, dist: this._dist(queryVector, d.vector) }));
      globalScored.sort((a, b) => a.dist - b.dist);
      const topGlobal = globalScored.slice(0, k * 2);
      const tenantFiltered = topGlobal.filter(d => d.tenantId === filterTenantId);
      return tenantFiltered.slice(0, k).map(d => d.id);
    }
    return this.exactSearch(queryVector, filterTenantId, k);
  }

  computeRecallAtK(groundTruthIds, annIds) {
    if (groundTruthIds.length === 0) return 1.0;
    const gtSet = new Set(groundTruthIds);
    const matched = annIds.filter(id => gtSet.has(id)).length;
    return matched / groundTruthIds.length;
  }
}

