  buildPrompt(systemDirective, userQuery, retrievedChunks) {
    const formattedChunks = retrievedChunks.map(c => {
      const sanitizedText = c.text.replace(/<\/untrusted_context>/g, '&lt;/untrusted_context&gt;').replace(/<\/context>/g, '&lt;/context&gt;');
      return '<untrusted_chunk id="' + c.id + '">\n' + sanitizedText + '\n</untrusted_chunk>';
