function queryLogInsights(logEntries, queryString) {
  let records = [...logEntries];
  const stages = queryString.split('|').map(s => s.trim()).filter(Boolean);

  for (const stage of stages) {
    const parts = stage.split(/\s+/);
    const command = parts[0].toLowerCase();

    if (command === 'filter') {
      const field = parts[1];
      const operator = parts[2];
      const rawVal = parts[3];
      const targetVal = isNaN(Number(rawVal)) ? rawVal.replace(/['"]/g, '') : Number(rawVal);

      records = records.filter(entry => {
        const val = entry[field];
        if (operator === '>=') return val >= targetVal;
        if (operator === '<=') return val <= targetVal;
        if (operator === '>') return val > targetVal;
        if (operator === '<') return val < targetVal;
        if (operator === '==' || operator === '=') return val == targetVal;
        if (operator === '!=') return val != targetVal;
        return true;
      });
    } else if (command === 'stats') {
      const byIndex = parts.findIndex(p => p.toLowerCase() === 'by');
      const groupField = byIndex !== -1 ? parts[byIndex + 1] : null;
      if (groupField) {
        const counts = {};
        for (const entry of records) {
          const key = String(entry[groupField]);
          counts[key] = (counts[key] || 0) + 1;
        }
        records = Object.entries(counts).map(([k, count]) => ({ [groupField]: isNaN(Number(k)) ? k : Number(k), count }));
      }
    } else if (command === 'sort') {
      const field = parts[1];
      const direction = (parts[2] || 'asc').toLowerCase();
      records.sort((a, b) => {
        const valA = a[field] ?? 0;
        const valB = b[field] ?? 0;
        return direction === 'desc' ? valB - valA : valA - valB;
      });
    }
  }
  return records;
}

