function calculateUSLThroughput(concurrencyN, sigmaContention, kappaCoherency) {
  const N = concurrencyN;
  const denominator = 1 + sigmaContention * (N - 1) + kappaCoherency * N * (N - 1);
  const throughput = N / denominator;

  const nextDenominator = 1 + sigmaContention * N + kappaCoherency * (N + 1) * N;
  const nextThroughput = (N + 1) / nextDenominator;

  return {
    throughput: Number(throughput.toFixed(4)),
    isRetrograde: nextThroughput < throughput
  };
}

function findPeakConcurrency(sigmaContention, kappaCoherency, maxN = 128) {
  let bestN = 1;
  let maxThroughput = 0;

  for (let n = 1; n <= maxN; n++) {
    const { throughput } = calculateUSLThroughput(n, sigmaContention, kappaCoherency);
    if (throughput > maxThroughput) {
      maxThroughput = throughput;
      bestN = n;
    }
  }
  return bestN;
}

