function evaluatePACELC(config) {
  const { engine, syncReplication, majorityQuorum, clientTimeoutMs } = config;

  const partitionChoice = (syncReplication || majorityQuorum) ? 'C' : 'A';
  const normalChoice = (syncReplication && majorityQuorum) ? 'C' : (syncReplication ? 'C' : 'L');

  const pacelcCode = `P${partitionChoice}/E${normalChoice}`;
  const rationale = partitionChoice === 'C'
    ? `Under network partition, ${engine} enforces consistency by rejecting writes that lack majority acknowledgment. Under normal operation, it trades off ${normalChoice === 'C' ? 'latency for strong consistency' : 'consistency for lower latency'}.`
    : `Under network partition, ${engine} accepts writes locally to preserve availability, trading off consistency. In normal operation, it provides low latency via asynchronous replication.`;

