function chunkDocument(text, chunkSizeWords = 50, overlapRatio = 0.10) {
  const words = text.trim().split(/\s+/).filter(Boolean);
  const step = Math.max(1, chunkSizeWords - Math.round(chunkSizeWords * overlapRatio));
  const chunks = [];
  let chunkIndex = 0;
  for (let i = 0; i < words.length; i += step) {
    const chunkWords = words.slice(i, i + chunkSizeWords);
    chunks.push({
      chunkIndex: chunkIndex++,
      text: chunkWords.join(' '),
      wordCount: chunkWords.length,
      startWord: i,
      endWord: i + chunkWords.length
    });
    if (i + chunkSizeWords >= words.length) break;
  }
  return chunks;
}

