      if (Date.now() - this.lastFailureTime > this.resetTimeout) this.state = 'HALF_OPEN';
      else throw new Error('CIRCUIT_OPEN_FAST_FAIL');
    }
    try {
      const res = await asyncFn();
      this.state = 'CLOSED';
      this.failures = 0;
