class JsxExpressionParser {
  normalizeAttributes(rawAttrs) {
    const names = { class: 'className', for: 'htmlFor', onclick: 'onClick', tabindex: 'tabIndex' };
    const props = {};
    for (const [key, value] of Object.entries(rawAttrs || {})) {
      if (key === 'style' && typeof value === 'string') {
        const style = {};
        for (const rule of value.split(';')) {
          const [prop, val] = rule.split(':').map((s) => s && s.trim());
          if (!prop || !val) continue;
          style[prop.replace(/-([a-z])/g, (_, c) => c.toUpperCase())] = val;
        }
        props.style = style;
      } else {
        props[names[key] || key] = value;
      }
    }
    return props;
  }
  evaluateExpression(context, expressionFn) {
    const result = expressionFn(context);
    return result === undefined ? null : result;
  }
  transpileTag(tagName, rawAttrs, evaluatedChildren) {
    const props = this.normalizeAttributes(rawAttrs);
    if (evaluatedChildren !== undefined) props.children = evaluatedChildren;
    return { type: tagName, props };
  }
}

