class EffectLifecycleScheduler {
  constructor() {
    this.activeCleanup = null;
    this.prevDeps = null;
    this.executionLog = [];
  }
  scheduleEffect(effectFn, nextDeps) {
    let shouldRun = false;
    if (this.prevDeps === null || !nextDeps) {
      shouldRun = true; // Initial run or omitted deps
    } else {
      // Compare each dependency using Object.is:
      shouldRun = nextDeps.some((dep, i) => !Object.is(dep, this.prevDeps[i]));
    }
    if (shouldRun) {
      if (this.activeCleanup) {
        this.executionLog.push('RUN_CLEANUP');
        this.activeCleanup();
      }
      this.executionLog.push('RUN_SETUP');
      this.activeCleanup = effectFn() || null;
      this.prevDeps = nextDeps ? [...nextDeps] : null;
    }
  }
  unmount() {
    if (this.activeCleanup) {
      this.executionLog.push('UNMOUNT_CLEANUP');
      this.activeCleanup();
      this.activeCleanup = null;
    }
  }
}

