  constructor() {
    this.state = { status: 'idle', data: null, error: null };
    this.actionHistory = [];
  }
  reducer(currentState, action) {
    const loading = { status: 'loading', data: null, error: null };
    switch (currentState.status) {
      case 'idle':
        return action.type === 'FETCH_START' ? loading : currentState;
      case 'loading':
        if (action.type === 'FETCH_SUCCESS') return { status: 'success', data: action.payload, error: null };
        if (action.type === 'FETCH_FAILURE') return { status: 'error', data: null, error: action.payload };
