// [TEACHING SIMULATION — Teaching Model: Client-Side Route Matcher Engine]
class ClientSideRouteMatcherEngine {
  constructor() {
    this.routes = []; // [{ pattern, component, isWildcard }]
  }
  addRoute(pattern, componentName) {
    this.routes.push({
      pattern,
      component: componentName,
      isWildcard: pattern === '*'
    });
  }
  match(rawPathname) {
    if (!rawPathname) return { matched: false, component: '', params: {} };
    // 1. Strip query string (?...) and hash fragment (#...)
    const cleanPath = rawPathname.split('?')[0].split('#')[0];
    // 2. Tokenize and percent-decode segments (ignoring leading/trailing empty slashes)
    const uSegs = cleanPath.split('/').filter(Boolean).map(s => decodeURIComponent(s));

    for (const r of this.routes) {
      if (r.isWildcard) continue;
      const pSegs = r.pattern.split('/').filter(Boolean);
      if (pSegs.length !== uSegs.length) continue;
      let match = true;
      const params = {};
      for (let i = 0; i < pSegs.length; i++) {
        if (pSegs[i].startsWith(':')) {
          params[pSegs[i].slice(1)] = uSegs[i];
        } else if (pSegs[i] !== uSegs[i]) {
          match = false;
          break;
        }
      }
      if (match) return { matched: true, component: r.component, params };
    }
    const wildcard = this.routes.find(r => r.isWildcard);
    if (wildcard) return { matched: true, component: wildcard.component, params: {} };
    return { matched: false, component: '', params: {} };
  }
}

