// [TEACHING SIMULATION — Teaching Model: URL State Navigation & History Engine]
class UrlStateNavigationEngine {
  constructor(initialSearch = '') {
    this.historyStack = [initialSearch];
    this.currentIndex = 0;
  }
  getCurrentSearch() {
    return this.historyStack[this.currentIndex] || '';
  }
  getQueryParams() {
    const params = {};
    const search = this.getCurrentSearch();
    if (!search) return params;
    const clean = search.startsWith('?') ? search.slice(1) : search;
    for (const pair of clean.split('&')) {
      if (!pair) continue;
      const [k, v] = pair.split('=');
      params[decodeURIComponent(k)] = decodeURIComponent(v || '');
    }
    return params;
  }
  updateQuery(updates, mode = 'push') {
    const current = this.getQueryParams();
    for (const [k, v] of Object.entries(updates)) {
      if (v === null || v === undefined || v === '') {
        delete current[k];
      } else {
        current[k] = String(v);
      }
    }
    const pairs = Object.entries(current).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v));
    const nextSearch = pairs.length > 0 ? '?' + pairs.join('&') : '';
    if (mode === 'push') {
      this.historyStack = this.historyStack.slice(0, this.currentIndex + 1);
      this.historyStack.push(nextSearch);
      this.currentIndex = this.historyStack.length - 1;
    } else if (mode === 'replace') {
      this.historyStack[this.currentIndex] = nextSearch;
    }
    return nextSearch;
  }
  back() {
    if (this.currentIndex > 0) {
      this.currentIndex--;
      return this.getCurrentSearch();
    }
    return this.getCurrentSearch();
  }
  forward() {
    if (this.currentIndex < this.historyStack.length - 1) {
      this.currentIndex++;
      return this.getCurrentSearch();
    }
    return this.getCurrentSearch();
  }
}

