                   metrics.lcp <= this.thresholds.lcpGood &&
                   metrics.cls <= this.thresholds.clsGood;
    return {
      metrics,
      isGood,
      inpRating: metrics.inp <= 200 ? 'GOOD' : metrics.inp <= 500 ? 'NEEDS_IMPROVEMENT' : 'POOR'
    };
  }
  processChunkedTasks(totalItems, chunkSize) {
    let yieldCount = 0;
    let processed = 0;
    for (let i = 0; i < totalItems; i += chunkSize) {
      processed += Math.min(chunkSize, totalItems - i);
      if (i + chunkSize < totalItems) yieldCount++;
    }
    return {
      totalProcessed: processed,
      yieldCount,
      mainThreadYielded: yieldCount > 0,
      strategy: 'PROGRESSIVE_TASK_YIELDING'
    };
  }
  reviewPullRequest(diffCode) {
    const violations = [];
    if (diffCode.includes('<div onClick')) violations.push('A11Y_NON_SEMANTIC_CLICK');
    if (diffCode.includes('{...props}') && diffCode.includes('variant=')) violations.push('PROP_LEAK_CUSTOM_VARIANT');
    if (diffCode.includes('wrapper.state(')) violations.push('TEST_PRIVATE_STATE_ASSERTION');

    return {
      isApproved: violations.length === 0,
      violations
    };
  }
