// [TEACHING SIMULATION — Teaching Model: Express 5 Middleware Engine]
class Express5MiddlewarePipelineEngine {
  constructor() {
    this.pipeline = [];
    this.errorHandler = null;
  }
  use(fn) { this.pipeline.push(fn); }
  useError(fn) { this.errorHandler = fn; }
  execute(req, res) {
    let idx = 0;
    const next = (err) => {
      if (err) {
        if (this.errorHandler) return this.errorHandler(err, req, res, () => {});
        res.status = 500; res.body = { error: 'Internal Error' }; return;
      }
      if (idx < this.pipeline.length) {
        const mw = this.pipeline[idx++];
        try {
          const result = mw(req, res, next);
          // In Express 5: handle returned promises
          if (result && typeof result.then === 'function') {
            result.catch(pErr => next(pErr));
          }
        } catch (syncErr) {
          next(syncErr);
        }
      }
    };
    next();
  }
  resolveIp(socketIp, forwardedHeader, isProxyTrusted) {
    if (isProxyTrusted && forwardedHeader) {
      const ips = forwardedHeader.split(',').map(s => s.trim());
      return { clientIp: ips[0], isTrusted: true, source: 'FORWARDED_CHAIN' };
    }
    return { clientIp: socketIp, isTrusted: false, source: 'SOCKET_REMOTE_ADDRESS' };
  }
