  formatProblemDetails(status, title, detail, instance, fieldErrors = []) {
    const problem = {
      type: `https://api.pinitcareer.com/errors/${status}`,
      title,
      status,
      detail,
      instance
    };
    if (fieldErrors.length > 0) problem.errors = fieldErrors;
    return {
      contentType: 'application/problem+json',
      status,
      body: problem
    };
  }
  mapError(type) {
    if (type === 'MALFORMED_JSON') return { status: 400, title: 'Bad Request' };
    if (type === 'SCHEMA_VALIDATION') return { status: 422, title: 'Unprocessable Content' };
    if (type === 'NOT_FOUND') return { status: 404, title: 'Not Found' };
    if (type === 'STATE_CONFLICT') return { status: 409, title: 'Conflict' };
    return { status: 500, title: 'Internal Server Error' };
  }
}

