class NormalizedUniversityCatalog {
  constructor() {
    this.students = new Map();
    this.courses = new Map();
    this.enrollments = new Map(); // Composite key: "studentId:courseId"
  }
  addStudent(id, name, email) {
    this.students.set(id, { id, name, email });
  }
  addCourse(id, code, credits) {
    this.courses.set(id, { id, code, credits });
  }
  enroll(studentId, courseId, grade) {
    if (!this.students.has(studentId)) throw new Error('23503: Student not found');
    if (!this.courses.has(courseId)) throw new Error('23503: Course not found');
    const compKey = studentId + ':' + courseId;
    if (this.enrollments.has(compKey)) {
      throw new Error('23505: Composite PK violation');
    }
    this.enrollments.set(compKey, { studentId, courseId, grade });
    return { success: true };
  }
}

