// [TEACHING SIMULATION — Concurrency Lock & Retry Manager]
class ConcurrencyLockManager {
  constructor(initialSeats = 1) {
    this.seats = initialSeats;
    this.locked = false;
  }
  async purchaseTicket(candidateId, simulateConflict = false) {
    // Retry loop for transient conflicts
    for (let attempt = 1; attempt <= 3; attempt++) {
      if (simulateConflict && attempt === 1) {
        // Simulating transient conflict (40001 / 40P01)
        continue;
      }
      // Row-Level Lock simulation (SELECT ... FOR UPDATE)
      while (this.locked) {
        await new Promise(r => setTimeout(r, 10));
      }
      this.locked = true;
      try {
        if (this.seats > 0) {
          this.seats--;
          return { success: true, candidateId, remainingSeats: this.seats };
        } else {
          return { success: false, candidateId, reason: 'SOLD_OUT' };
        }
      } finally {
        this.locked = false;
      }
    }
    return { success: false, candidateId, reason: 'RETRY_EXHAUSTED' };
  }
}

