class DoubleSubmitCsrfValidator {
  constructor(secretKey, hmacSha256Hex, randomHex) {
    this.secretKey = secretKey;
    this.hmac = hmacSha256Hex;
    this.randomHex = randomHex;
  }

  generateToken(sessionId) {
    const raw = this.randomHex(16);
    return raw + '.' + this.hmac(this.secretKey, sessionId + ':' + raw);
  }

  validate(cookieToken, headerToken, activeSessionId) {
    if (!cookieToken || !headerToken) return { valid: false, code: 'CSRF_TOKEN_MISSING' };
    if (typeof cookieToken !== 'string' || typeof headerToken !== 'string') return { valid: false, code: 'CSRF_TOKEN_MALFORMED' };
    if (cookieToken.length !== headerToken.length) return { valid: false, code: 'CSRF_TOKEN_WRONG_LENGTH' };
    let diff = 0;
    for (let i = 0; i < cookieToken.length; i++) diff |= cookieToken.charCodeAt(i) ^ headerToken.charCodeAt(i);
    if (diff !== 0) return { valid: false, code: 'CSRF_TOKEN_TAMPERED' };
    const [raw, sig] = headerToken.split('.');
    if (!raw || !sig || sig !== this.hmac(this.secretKey, activeSessionId + ':' + raw)) return { valid: false, code: 'CSRF_SESSION_MISMATCH' };
    return { valid: true, code: 'OK' };
  }
}

