class EnvelopeEncryptionEngine {
  constructor(masterKek, aead, randomHex) {
    this.masterKek = masterKek;
    this.aead = aead;
    this.randomHex = randomHex;
  }

  encryptField(plaintext, ctx) {
    const dek = this.randomHex(32);
    const aad = `${ctx.tenantId}:${ctx.recordId}:${ctx.fieldName}:${ctx.version}`;
    const data = this.aead.seal(dek, plaintext, aad);
    const wrapped = this.aead.seal(this.masterKek, dek);
    return { encryptedDek: JSON.stringify(wrapped), iv: data.iv, ciphertext: data.ciphertext, authTag: data.tag };
  }

  decryptField(payload, ctx) {
    const dek = this.aead.open(this.masterKek, JSON.parse(payload.encryptedDek));
    const aad = `${ctx.tenantId}:${ctx.recordId}:${ctx.fieldName}:${ctx.version}`;
    return this.aead.open(dek, { iv: payload.iv, ciphertext: payload.ciphertext, tag: payload.authTag }, aad);
  }
}

