  for (const v of ranked) {
    if (remaining <= 0) break;
    const routedQty = Math.min(remaining, v.availableQty);
    allocations.push({ venue: v.name, routedQty, price: v.askPrice });
    remaining -= routedQty;
  }
  return { allocations, totalFilled: qty - remaining, remainingUnfilled: remaining };
}

quant-systems-exam-day-24:
function calculateFiberLatency(meters, n = 1.4682) {
  const speedInFiber = 299792458 / n;
  const nanos = (meters / speedInFiber) * 1e9;
  return { propagationTimeNanoseconds: nanos, nanosecondsPerMeter: Number((1e9 / speedInFiber).toFixed(3)) };
}

quant-systems-exam-day-25:
function simulateMicrowaveNetwork(distKm, towers, hopDelayNs, rainRate) {
  const airSpeed = 299792.458 / 1.0003;
  const totalOneWayLatencyMs = Number(((distKm / airSpeed) * 1000 + (towers * hopDelayNs) / 1e6).toFixed(3));
  const isSignalDegraded = rainRate >= 25;
  return {
    totalOneWayLatencyMs,
    isSignalDegraded,
    pathStatus: isSignalDegraded ? 'FAILOVER_TO_FIBER_BACKUP' : 'MICROWAVE_ACTIVE_LOW_LATENCY'
  };
}

