    violations,
    violationsCount: violations.length,
    isTemporalIntegrityPreserved: violations.length === 0
  };
}

quant-systems-exam-day-27:
function validatePreTradeRisk(order, limits, midPrice) {
  if (order.qty > limits.maxQty) return { approved: false, reason: 'MAX_QTY_BREACH' };
  if (order.qty * order.price > limits.maxNotional) return { approved: false, reason: 'MAX_NOTIONAL_BREACH' };
  if (Math.abs(order.price - midPrice) / midPrice > limits.maxPriceCollar) return { approved: false, reason: 'PRICE_COLLAR_BREACH' };
  return { approved: true, reason: null };
}

