quant-systems-exam-day-3:
function matchIncomingOrder(book, order) {
  const resting = order.side === 'BUY' ? book.asks : book.bids;
  const crosses = (p) => (order.side === 'BUY' ? order.price >= p : order.price <= p);
  const trades = [];
  let remaining = order.qty;
  while (remaining > 0 && resting.length && crosses(resting[0].price)) {
    const top = resting[0];
    const qty = Math.min(remaining, top.qty);
    trades.push({ price: top.price, qty, restingOrderId: top.id, incomingOrderId: order.id });
    top.qty -= qty;
    remaining -= qty;
    if (top.qty === 0) resting.shift();
  }
  return { trades, remainingQty: remaining };
}

quant-systems-exam-day-30:
function orchestrateQuantHftSystem(packet, risk, params) {
  const breaches = packet.qty > risk.maxQty
    || packet.qty * packet.price > risk.maxNotional
    || Math.abs(packet.price - params.mid) / params.mid > risk.maxPriceCollar;
  const reservationPrice = params.mid - params.inventory * params.gamma * params.sigma * params.sigma;
  return {
    executionApproved: !breaches,
    reservationPrice: Number(reservationPrice.toFixed(4)),
    systemStatus: breaches ? 'RISK_REJECTED' : 'HFT_SOVEREIGN_SYSTEM_ONLINE'
  };
}

